import operator
from typing import Any, Callable

_CMP_OPS = {
    "=": operator.eq,
    "!=": operator.ne,
    "<": operator.lt,
    "<=": operator.le,
    ">": operator.gt,
    ">=": operator.ge,
}


# --------------------------------------------------------------------------
# Three-valued logic helpers (True / False / None == UNKNOWN)
# --------------------------------------------------------------------------
def _tv_and(a, b):
    if a is False or b is False:
        return False
    if a is None or b is None:
        return None
    return True


def _tv_or(a, b):
    if a is True or b is True:
        return True
    if a is None or b is None:
        return None
    return False


def _tv_not(a):
    return None if a is None else (not a)


def _tv_cmp(op, a, b):
    if a is None or b is None:
        return None
    return op(a, b)


# --------------------------------------------------------------------------
# Condition compilation: every compiled piece is fn(row, aggs) -> value
#   row  : dict giving column values (a data row, or a group's first row)
#   aggs : dict {(func, arg): value} with the group's aggregates (or {})
# --------------------------------------------------------------------------
def _compile_operand(x) -> Callable[[dict, dict], Any]:
    kind = x[0]
    if kind == "col":
        name = x[1]
        return lambda row, aggs: row[name]
    if kind == "val":
        lit = x[1]
        return lambda row, aggs: lit
    if kind == "agg":
        key = (x[1], x[2])
        return lambda row, aggs: aggs[key]
    raise ValueError(f"unknown operand {x!r}")


def _compile_cond(cond) -> Callable[[dict, dict], Any]:
    op = cond[0]

    if op in _CMP_OPS:
        fn = _CMP_OPS[op]
        fx = _compile_operand(cond[1])
        fy = _compile_operand(cond[2])
        return lambda row, aggs: _tv_cmp(fn, fx(row, aggs), fy(row, aggs))

    if op == "and":
        fa = _compile_cond(cond[1])
        fb = _compile_cond(cond[2])
        return lambda row, aggs: _tv_and(fa(row, aggs), fb(row, aggs))

    if op == "or":
        fa = _compile_cond(cond[1])
        fb = _compile_cond(cond[2])
        return lambda row, aggs: _tv_or(fa(row, aggs), fb(row, aggs))

    if op == "not":
        fa = _compile_cond(cond[1])
        return lambda row, aggs: _tv_not(fa(row, aggs))

    if op == "is_null":
        fx = _compile_operand(cond[1])
        return lambda row, aggs: fx(row, aggs) is None

    if op == "in":
        fx = _compile_operand(cond[1])
        lst = list(cond[2])
        has_null = any(v is None for v in lst)
        non_null = set(v for v in lst if v is not None)
        empty = len(lst) == 0

        def f_in(row, aggs):
            if empty:
                return False
            v = fx(row, aggs)
            if v is None:
                return None
            if v in non_null:
                return True
            return None if has_null else False

        return f_in

    if op == "between":
        fx = _compile_operand(cond[1])
        lo = cond[2]
        hi = cond[3]

        def f_between(row, aggs):
            v = fx(row, aggs)
            return _tv_and(_tv_cmp(operator.ge, v, lo), _tv_cmp(operator.le, v, hi))

        return f_between

    raise ValueError(f"unknown condition {cond!r}")


def _collect_aggs(cond, out: set):
    """Collect all (func, arg) referenced by ["agg", func, arg] operands."""
    if not isinstance(cond, list) or not cond:
        return
    if cond[0] == "agg" and len(cond) == 3 and isinstance(cond[1], str):
        out.add((cond[1], cond[2]))
        return
    for part in cond[1:]:
        if isinstance(part, list):
            _collect_aggs(part, out)


# --------------------------------------------------------------------------
# Aggregates
# --------------------------------------------------------------------------
def _compute_agg(func: str, arg: str, grows: list) -> Any:
    if func == "count":
        if arg == "*":
            return len(grows)
        return sum(1 for r in grows if r[arg] is not None)
    vals = [r[arg] for r in grows if r[arg] is not None]
    if func == "count_distinct":
        return len(set(vals))
    if not vals:
        return None
    if func == "sum":
        return sum(vals)
    if func == "min":
        return min(vals)
    if func == "max":
        return max(vals)
    if func == "avg":
        return sum(vals) // len(vals)  # floor division, also for negatives
    raise ValueError(f"unknown aggregate {func!r}")


# --------------------------------------------------------------------------
# Main entry point
# --------------------------------------------------------------------------
def run_query(rows: list[dict], query: dict) -> list[dict]:
    select = query.get("select") or []
    where = query.get("where")
    group_by = query.get("group_by") or []
    having = query.get("having")
    distinct = bool(query.get("distinct"))
    order_by = query.get("order_by") or []
    offset = query.get("offset")
    limit = query.get("limit")

    # ---- WHERE ----------------------------------------------------------
    if where is not None:
        wf = _compile_cond(where)
        empty = {}
        passing = [r for r in rows if wf(r, empty) is True]
    else:
        passing = list(rows)

    # ---- classify select items -----------------------------------------
    select_aggs = [(item[0], item[1]) for item in select if isinstance(item, list)]
    has_aggs = bool(select_aggs)
    grouped = has_aggs or bool(group_by)

    if grouped:
        # aggregates needed: from select and having
        needed = set(select_aggs)
        if having is not None:
            _collect_aggs(having, needed)
        needed = list(needed)

        # ---- GROUPING (hash based, insertion order = first appearance) ---
        groups: dict[tuple, list] = {}
        if group_by:
            gcols = list(group_by)
            for r in passing:
                key = tuple(r[c] for c in gcols)
                bucket = groups.get(key)
                if bucket is None:
                    groups[key] = [r]
                else:
                    bucket.append(r)
        else:
            groups[()] = passing  # exactly one group, even if empty

        # ---- HAVING + SELECT per group ----------------------------------
        hf = _compile_cond(having) if having is not None else None
        out_rows = []
        for key, grows in groups.items():
            first = grows[0] if grows else None
            aggs = {fa: _compute_agg(fa[0], fa[1], grows) for fa in needed}

            if hf is not None:
                # group column lookup: values from the group's first row
                if first is not None:
                    colrow = first
                else:
                    colrow = {}
                if hf(colrow, aggs) is not True:
                    continue

            out = {}
            for item in select:
                if isinstance(item, list):
                    func, arg = item[0], item[1]
                    out[f"{func}({arg})"] = aggs[(func, arg)]
                else:
                    out[item] = first[item] if first is not None else None
            out_rows.append(out)
    else:
        # ---- plain projection -------------------------------------------
        cols = list(select)
        out_rows = [{c: r[c] for c in cols} for r in passing]

    # ---- DISTINCT -------------------------------------------------------
    if distinct:
        seen = set()
        deduped = []
        for r in out_rows:
            k = tuple(r.values())
            if k not in seen:
                seen.add(k)
                deduped.append(r)
        out_rows = deduped

    # ---- ORDER BY (stable sorts from last key to first) ------------------
    for spec in reversed(order_by):
        key = spec[0]
        direction = spec[1] if len(spec) > 1 and spec[1] else "asc"
        nulls = spec[2] if len(spec) > 2 else None
        reverse = direction == "desc"
        if nulls is None:
            nulls_first = not reverse  # NULL smallest: first for asc, last for desc
        else:
            nulls_first = nulls == "first"
        # rank so that, after (possibly reversed) sort, nulls land where wanted
        if reverse:
            null_rank, val_rank = (1, 0) if nulls_first else (0, 1)
        else:
            null_rank, val_rank = (0, 1) if nulls_first else (1, 0)

        def sort_key(r, key=key, nr=null_rank, vr=val_rank):
            v = r[key]
            if v is None:
                return (nr, 0)
            return (vr, v)

        out_rows.sort(key=sort_key, reverse=reverse)

    # ---- OFFSET / LIMIT -------------------------------------------------
    if offset:
        out_rows = out_rows[offset:]
    if limit is not None:
        out_rows = out_rows[:limit]

    return out_rows
